INSERT INTO spawn2 (`id`, `spawngroupID`, `zone`, `version`, `x`, `y`, `z`, `heading`, `respawntime`, `variance`, `pathgrid`, `path_when_zone_idle`, `_condition`, `cond_value`, `animation`, `min_expansion`, `max_expansion`, `content_flags`, `content_flags_disabled`)
SELECT 304096000+n.ordinal-1, s.`spawngroupID`, s.`zone`, 20, s.`x`, s.`y`, s.`z`, s.`heading`, s.`respawntime`, s.`variance`, s.`pathgrid`, s.`path_when_zone_idle`, s.`_condition`, s.`cond_value`, s.`animation`, s.`min_expansion`, s.`max_expansion`, s.`content_flags`, s.`content_flags_disabled`
FROM spawn2 s
JOIN (
    SELECT id, ROW_NUMBER() OVER (ORDER BY id) AS ordinal
    FROM spawn2 WHERE zone='ashengate' AND version=0
) n ON n.id=s.id
WHERE s.zone='ashengate' AND s.version=0 AND (s.y < 25 OR s.x < -150)
  AND NOT EXISTS (
      SELECT 1 FROM spawnentry e JOIN npc_types t ON t.id=e.npcID
      WHERE e.spawngroupID=s.spawngroupID
        AND (t.class IN (40,41,61,62) OR t.name LIKE '#%' OR t.id IN (406081,406090,406117))
  );

